solution:
record Producto(String nombre, double precio) {
    Producto {
        if (nombre == null || nombre.isEmpty()) {
            throw new IllegalArgumentException("Nombre no puede ser null o vacio");
        }
        if (precio <= 0) {
            throw new IllegalArgumentException("Precio debe ser mayor a 0");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            Producto p1 = new Producto("Laptop", 999.99);
            Producto p2 = new Producto("Mouse", 25.50);
            System.out.println(p1);
            System.out.println(p2);
        } catch (IllegalArgumentException e) {
            System.out.println("Error: " + e.getMessage());
        }

        try {
            Producto p3 = new Producto("Teclado", -10.0);
            System.out.println(p3);
        } catch (IllegalArgumentException e) {
            System.out.println("Error precio: " + e.getMessage());
        }

        try {
