record Direccion(String calle, String ciudad) {}

record Persona(String nombre, int edad, Direccion direccion) {}

public class Main {

    static String obtenerCiudad(Persona p) {
        return p.direccion().ciudad();
    }

    public static void main(String[] args) {
        Persona p1 = new Persona("Ana", 25, new Direccion("Av. Principal", "Lima"));
        Persona p2 = new Persona("Luis", 30, new Direccion("Calle 5", "Cusco"));

        System.out.println(p1);
        System.out.println(p2);

        System.out.println("Ciudad de Ana: " + obtenerCiudad(p1));
        System.out.println("Ciudad de Luis: " + obtenerCiudad(p2));

        System.out.println("Calle de Luis: " + p2.direccion().calle());
    }
}
